 // Copyright(c) The Maintainers of Nanvix.
 // Licensed under the MIT License.

 //! Kernel frame pool — module-level singleton.
 //!
 //! The kernel pool is backed by a [`Bitmap`] and exposed as free functions over a singleton so
 //! every in-kernel caller goes through the same state. The public facade types [`Kpool`] and
 //! [`KernelFrame`] delegate to the singleton.
 //!
 //! Access to the kernel pool is synchronized externally and performed by a single thread, so
 //! the backing bitmap uses non-atomic operations.

 //==================================================================================================
 // Imports
 //==================================================================================================

 use crate::{
     collections::Bitmap,
     hal::{
         mem::{
             Address,
             FrameAddress,
             PageAligned,
             PhysicalAddress,
         },
         platform::is_valid_physical_region,
     },
 };
 #[cfg(verus_keep_ghost)]
 use crate::collections::BitmapView;
 #[cfg(verus_keep_ghost)]
 use crate::hal::mem::spec_page_size;
 use ::alloc::vec::Vec;
 use ::arch::mem;
 use ::core::{
     hint::unlikely,
     mem::MaybeUninit,
     ops::{
         Deref,
         DerefMut,
     },
     sync::atomic::{
         AtomicBool,
         Ordering,
     },
 };
 use ::sys::error::{
     Error,
     ErrorCode,
 };

 use ::vstd::prelude::*;

 #[cfg(verus_keep_ghost)]
 include!("kpool.spec.rs");

 #[cfg(verus_keep_ghost)]
 include!("kpool.proof.rs");

 //==================================================================================================
 // Inner
 //==================================================================================================

 /// Private state of the kernel pool singleton.
 #[verus_verify(external_derive)]
 struct Inner {
     /// Base address of the kernel pool.
     base: PageAligned<PhysicalAddress>,
     /// Bitmap of free frames.
     bitmap: Bitmap,
 }

 /// Wrapper: converts a [`PageAligned<PhysicalAddress>`] to its raw `usize` value.
 #[verus_verify(external_body)]
 #[verus_spec(ret =>
     ensures ret as int == pa@,
 )]
 fn pa_into_raw(pa: PageAligned<PhysicalAddress>) -> usize {
     pa.into_raw_value()
 }

 /// Wrapper: constructs a [`FrameAddress`] from a raw address.
 #[verus_verify(external_body)]
 #[verus_spec(result =>
     requires raw_addr as int % spec_page_size() == 0,
     ensures
         result.is_Ok(),
         match result {
             Ok(frame) => {
                 &&& frame@ == raw_addr as int
                 &&& frame.inv()
             },
             Err(_) => false,
         },
 )]
 fn frame_from_raw(raw_addr: usize) -> Result<FrameAddress, Error> {
     Ok(FrameAddress::new(PageAligned::from_address(
         PhysicalAddress::from_raw_value(raw_addr)?,
     )?))
 }

